import { parseCommandLine } from './lib/argument-parser.mjs';
import {
  ConstructBuildError,
  buildFixedBytes,
  buildInt16ul,
  buildInt8ul,
  encodeUtf8,
} from './lib/construct.mjs';
import { pythonModulo } from './lib/python-int.mjs';
import { bytesToPythonRepr } from './lib/python-repr.mjs';

export function buildFormats(args) {
  return [
    buildInt8ul(args.a),
    buildInt16ul(args.b),
    buildFixedBytes(args.d, encodeUtf8(args.c)),
    buildInt8ul(args.f),
    buildFixedBytes(args.g, encodeUtf8(args.e)),
    buildInt8ul(pythonModulo(args.f + args.g, 256n)),
    buildInt8ul(pythonModulo(args.a + args.b, 256n)),
  ];
}

export function main(argv = process.argv) {
  const args = parseCommandLine(argv);
  if (args === null) {
    return;
  }

  for (const bytes of buildFormats(args)) {
    console.log(bytesToPythonRepr(bytes));
  }
}

try {
  main();
} catch (error) {
  if (error instanceof ConstructBuildError) {
    const errorType =
      error.category === 'format'
        ? 'construct.core.FormatFieldError'
        : 'construct.core.StreamError';
    console.error(`${errorType}: Error in path (building)`);
    console.error(error.message);
    process.exitCode = error.exitCode;
  } else {
    throw error;
  }
}

